Object.assign(JA_CRITERIA,{1:{item:'適切な目標設定',perspective:'パーパス「化学の力で社会を変える」を実現するために、挑戦的な目標と目指すべき将来像が具体的に定義されているか。',score5:'達成が極めて困難な、非常に挑戦的で高い目標が明確に定義されている。',score3:'達成が困難な挑戦的目標が明確に定義されている。',score1:'目標が不明確、または容易に達成できる水準の目標が設定されている。'},2:{item:'バリュー実践へのコミットメント',perspective:'目標達成のプロセスにおいて、どの程度バリューを実践し、工夫と努力を示しているか。',score5:'バリューを意識した行動が数多く実践されている。',score3:'バリューを反映した行動が一定程度評価できる。',score1:'バリューを反映した行動が見られない。'},3:{item:'達成度と成果のインパクト',perspective:'年度目標に対する達成度と、組織へのインパクトの大きさ。',score5:'目標を上回って達成し、組織に大きなインパクトを与えている。',score3:'目標を達成し、組織へのインパクトを一定程度評価できる。',score1:'目標が未達、または組織展開とインパクトが極めて限定的である。'}});

function evaluationTarget(no){const target=no===1?{key:'goal',weight:20}:no===2?{key:'process',weight:30}:{key:'results',weight:50};const names=judgeLang==='ja'?{goal:'目標',process:'プロセス',results:'成果'}:{goal:'Goal',process:'Process',results:'Results'};return{...target,name:names[target.key],heading:judgeLang==='ja'?'評価対象':'Evaluation Target'};}

openScore=function(id){team=data.teams.find(t=>t.id===id);const old=(data.myScores||{})[id]?.ratings||{},t=judgeText(),scoreOptions=[5,4.5,4,3.5,3,2.5,2,1.5,1];const criterionCard=c=>{const d=judgeLang==='ja'?{...c,...JA_CRITERIA[c.no]}:c,guides=[5,4,3,2,1].filter(n=>d['score'+n]).map(n=>`<p><b>${t.score} ${n}:</b> ${esc(d['score'+n])}</p>`).join('');return `<div class="criterion"><div><h3>${esc(c.no)}. ${esc(d.item)} (${c.weight}%)</h3><p>${esc(d.perspective)}</p></div><div class="scale">${scoreOptions.map(n=>`<label title="${esc(d['score'+n]||'')}"><input name="c${c.no}" type="radio" value="${n}" ${+old[c.no]===n?'checked':''} onchange="calc()">${n}</label>`).join('')}</div>${guides?`<details class="score-guide"><summary>${t.guide}</summary>${guides}</details>`:''}</div>`};const groups=[1,2,3].map(no=>evaluationTarget(no)).map(target=>`<section class="target-card"><div class="target-card-head"><span>${target.heading}</span><b>${target.name}</b><em>${target.weight}%</em></div><div class="target-criteria">${data.criteria.filter(c=>evaluationTarget(c.no).key===target.key).map(criterionCard).join('')}</div></section>`).join('');const html=`<div class="score-page"><div class="score-title"><h2>${esc(team.no)}. ${esc(team.name)}</h2><p>${esc(team.theme)}</p></div><div id="total" class="total"></div><div class="criteria-list">${groups}</div><div class="foot"><button class="alt" onclick="closeScore()">${t.cancel}</button><button onclick="saveScore()">${t.save}</button></div></div>`;Swal.fire({...swalTheme,html,showConfirmButton:false,showCloseButton:true,allowOutsideClick:false,allowEscapeKey:false,customClass:{popup:'score-swal-popup',htmlContainer:'score-swal-html'}});setTimeout(calc,0)};

adminView=function(){const all=data.results||[],expected=data.teams.length*data.judgeCount,percent=expected?data.scoreCount/expected*100:0,r=filteredAdminResults();const tabs=`<nav class="admin-nav"><button class="${adminTab==='results'?'active':''}" onclick="setAdminTab('results')">สรุปผล</button><button class="${adminTab==='teams'?'active':''}" onclick="setAdminTab('teams')">จัดการทีม</button><button class="${adminTab==='users'?'active':''}" onclick="setAdminTab('users')">จัดการผู้ใช้</button></nav>`;const progress=`<section class="panel"><div class="head"><h2>ความคืบหน้ากรรมการ</h2><span class="hint">${data.scoreCount} / ${expected} รายการ (${percent.toFixed(1)}%)</span></div><div class="judge-progress-grid">${(data.judgeProgress||[]).map(j=>{const p=j.total?j.scored/j.total*100:0;return`<article class="judge-progress"><b>${esc(j.name)}</b><span>${j.scored} / ${j.total} ทีม</span><div><i style="width:${p}%"></i></div></article>`}).join('')}</div></section>`;const results=`<section class="panel"><div class="head"><h2>ตารางผลคะแนน</h2><div class="result-actions"><button class="alt" onclick="exportAdminExcel()">Export Excel</button><label class="result-filter">แสดง<select onchange="setAdminFilter(this.value)"><option value="all" ${adminFilter==='all'?'selected':''}>ทั้งหมด</option><option value="final" ${adminFilter==='final'?'selected':''}>ครบแล้ว</option><option value="pending" ${adminFilter==='pending'?'selected':''}>ยังไม่ครบ</option></select></label></div></div><div class="table-wrap"><table><thead><tr><th>อันดับ</th><th>ทีม</th><th>สถานะ</th><th class="right">รวม</th><th class="right">Goal</th><th class="right">Process</th><th class="right">Results</th><th class="right">ประเมินแล้ว</th></tr></thead><tbody>${r.map(x=>{const final=x.judges===data.judgeCount;return`<tr><td>${x.rank||'—'}</td><td><b>${esc(x.name)}</b><small>${esc(x.theme)}</small></td><td><span class="tag ${final?'done':'pending'}">${final?'Final':'Provisional'}</span></td><td class="right"><b>${x.judges?(+x.average).toFixed(2):'—'}</b></td><td class="right">${x.judges?(+x.goal).toFixed(1):'—'}</td><td class="right">${x.judges?(+x.process).toFixed(1):'—'}</td><td class="right">${x.judges?(+x.results).toFixed(1):'—'}</td><td class="right">${x.judges}/${data.judgeCount}</td></tr>`}).join('')||'<tr><td colspan="8">ไม่พบข้อมูลตามตัวกรอง</td></tr>'}</tbody></table></div></section>`;const teams=`<section class="panel"><div class="head"><h2>เพิ่มทีมแข่งขัน</h2><span class="hint">กำหนดลำดับและรหัสทีมอัตโนมัติ</span></div><div class="formrow"><label>ชื่อทีม<input id="tn"></label><label>Theme<input id="tt"></label><label>ผู้นำเสนอ<input id="tp"></label><label>แผนก<input id="td"></label><button onclick="addTeam()">เพิ่มทีม</button></div><div id="teamError" class="error"></div></section>`;const users=`<section class="panel"><div class="head"><h2>เพิ่มผู้ใช้</h2><span class="hint">เพิ่มกรรมการหรือผู้ดูแลระบบ</span></div><div class="formrow"><label>ชื่อ<input id="un"></label><label>Username<input id="uu"></label><label>Password<input id="up" type="password"></label><label>สิทธิ์<select id="ur"><option value="judge">กรรมการ</option><option value="admin">Admin</option></select></label><button onclick="addUser()">เพิ่มผู้ใช้</button></div><div id="userError" class="error"></div></section>`;const summary=`<div class="stats"><div class="stat"><small>ทีมแข่งขัน</small><b>${data.teams.length}</b></div><div class="stat"><small>กรรมการ</small><b>${data.judgeCount}</b></div><div class="stat"><small>ความคืบหน้า</small><b>${percent.toFixed(1)}%</b><small>${data.scoreCount}/${expected} รายการ</small></div></div>`;return`${summary}${tabs}${adminTab==='results'?progress+results:adminTab==='teams'?teams:users}`};
Object.assign(JA_CRITERIA,{1:{item:'目標設定の適切さ',perspective:'パーパス「化学の力で社会を変える」を実現するために、チャレンジングな目標、ありたい姿を具体的に設定できているか。',score5:'達成が非常に困難な高い目標が明確に設定されている。',score3:'達成が困難な目標が明確に設定されている。',score1:'目標が不明確、あるいは達成が容易な目標設定である。'},2:{item:'バリュー実践の姿勢',perspective:'目標達成のためにどれだけバリューを実践し、どれだけ工夫をしているか？\n\n※4つのバリュー\n「プロフェッショナルとしての成果へのこだわり」\n「枠を超えるオープンマインド」\n「機敏さと柔軟性」\n「未来への先見性と高い倫理観」',score5:'バリューを意識した多くの行動を実践している。',score3:'バリューを意識した行動について評価ができる。',score1:'バリューを意識した行動が見られない。'},3:{item:'目標に対する達成度、成果の大きさ',perspective:'当年の目標に対する達成度（成果の大きさ）と、その組織的なインパクトの大きさ。',score5:'目標を上回る達成をし、組織的にも影響力の大きな成果を上げている。',score3:'目標を達成し、組織的な影響力について一定の評価ができる。',score1:'目標を達成していない、あるいは活動を横展開できる範囲が非常に限定的である。'}});

// Use a compact dropdown for the original 0.5-point Excel scale.
calc=function(){let sum=0;data.criteria.forEach(c=>{const q=document.querySelector(`select[name="c${c.no}"]`);if(q&&q.value!=='')sum+=Number(q.value)/5*Number(c.weight)});$('total').textContent=`${judgeText().total}: ${sum.toFixed(2)} / 100`};
saveScore=async function(){const ratings={},t=judgeText();for(const c of data.criteria){const q=document.querySelector(`select[name="c${c.no}"]`);if(!q||q.value===''){notify('warning',t.incomplete,t.selectAll);return}ratings[c.no]=Number(q.value)}if(!await confirmAction(t.confirmSave,team.name,t.save,t.cancel))return;loading(t.saving);try{const r=await rpc('saveScore',token,{teamId:team.id,ratings});data=r.data;render();Swal.close();notify('success',t.saved)}catch(e){Swal.close();notify('error',t.saveError,e.message)}};
openScore=function(id){team=data.teams.find(t=>t.id===id);const old=(data.myScores||{})[id]?.ratings||{},t=judgeText(),options=[5,4.5,4,3.5,3,2.5,2,1.5,1];const criterionCard=c=>{const d=judgeLang==='ja'?{...c,...JA_CRITERIA[c.no]}:c,guides=[5,4,3,2,1].filter(n=>d['score'+n]).map(n=>`<p><b>${t.score} ${n}:</b> ${esc(d['score'+n])}</p>`).join('');return `<div class="criterion"><div><h3>${esc(c.no)}. ${esc(d.item)} (${c.weight}%)</h3><p>${esc(d.perspective)}</p></div><div class="score-select"><select name="c${c.no}" onchange="calc()"><option value="">Select score</option>${options.map(n=>`<option value="${n}" ${Number(old[c.no])===n?'selected':''}>${n}</option>`).join('')}</select></div>${guides?`<details class="score-guide" open><summary>${t.guide}</summary>${guides}</details>`:''}</div>`};const groups=[1,2,3].map(no=>evaluationTarget(no)).map(target=>`<section class="target-card"><div class="target-card-head"><span>${target.heading}</span><b>${target.name}</b><em>${target.weight}%</em></div><div class="target-criteria">${data.criteria.filter(c=>evaluationTarget(c.no).key===target.key).map(criterionCard).join('')}</div></section>`).join('');const html=`<div class="score-page"><div class="score-title"><h2>${esc(team.no)}. ${esc(team.name)}</h2><p>${esc(team.theme)}</p></div><div id="total" class="total"></div><div class="criteria-list">${groups}</div><div class="foot"><button class="alt" onclick="closeScore()">${t.cancel}</button><button onclick="saveScore()">${t.save}</button></div></div>`;Swal.fire({...swalTheme,html,showConfirmButton:false,showCloseButton:true,allowOutsideClick:false,allowEscapeKey:false,customClass:{popup:'score-swal-popup',htmlContainer:'score-swal-html'}});setTimeout(calc,0)};

function updateHeaderActions(language){const ja=language==='ja';$('scheduleButton').textContent=ja?'スケジュール':'Schedule';$('loginGuide').textContent=ja?'マニュアル':'Manual';}
render=function(){if(data.user.role==='admin'){updateHeaderActions('en');$('content').innerHTML=adminView();addResultActions();return}const t=judgeText();$('headerSubtitle').textContent=t.subtitle;$('logout').textContent=t.signOut;updateHeaderActions(judgeLang);$('content').innerHTML=judgeView()};
